{"version":3,"file":"build-agent-chat-Bj6r_tip.js","sources":["../../../widgets/build-agent-chat.js"],"sourcesContent":["import {html} from 'lit';
import {customElement} from 'lit/decorators.js';
import {AIUXElement} from '@servicenow/aiux/aiux-components-core';
import {i18n} from '@servicenow/aiux/aiux-services';

const STUDIO_URL =
  '/now/servicenow-studio?table=sys_app&sysId=a4fd2da13bf8be5062f31831a3e45ac9';

@customElement('wdf-build-agent-chat')
export class WdfBuildAgentChat extends AIUXElement {
  static properties = {
    ...AIUXElement.properties,
    _key: {type: Number, state: true}
  };

  constructor() {
    super();
    this._key = 0;
  }

  render() {
    return html`
      <section class="flex flex-col gap-2">
        <div class="flex flex-wrap items-center justify-between gap-2">
          <h3 class="text-xl font-semibold text-text-primary">
            ${i18n.getMessage('Build it with Build Agent')}
          </h3>
          <button
            class="aiux-btn aiux-btn-outline aiux-btn-sm"
            @click=${() => {
              this._key += 1;
            }}
          >
            ${i18n.getMessage('Reset panel')}
          </button>
        </div>
        <iframe
          src="${STUDIO_URL}&r=${this._key}"
          title="${i18n.getMessage('ServiceNow Studio')}"
          class="h-[calc(100vh-8rem)] min-h-[40rem] w-full rounded-xl border border-base-300"
        ></iframe>
      </section>
    `;
  }
}
